     line, = ax.plot([],[])
     def update(frame):
         line.set_data(data['x'][:frame+1],data['y'][:frame+1])
         return (line,)
     update(data['frame'])
     result = {'shownY':list(line.get_ydata()),'lineCount':len(ax.lines)}
     plt.close(fig)
     return result
